fig,ax=plt.subplots(figsize=(8.2,3.4)); ax.bar(labels,[100*student['models'][n]['top1_including_misses'] for n in names],color='#0891b2');ax.set_ylim(0,100);ax.set_ylabel('Proxy top-1 incl. misses (%)');ax.set_title('Student-test classifier-only comparison');fig.tight_layout();fig.savefig(output/'student_heading.png',dpi=150);plt.close(fig)
fig,(ax1,ax2)=plt.subplots(1,2,figsize=(8.2,3.4)); ax1.bar(labels,[x['candidate_macro_f1_mean'] for x in cvrows],color='#7c3aed');ax1.set_ylim(0,1);ax1.set_title('Training CV candidate macro F1');ax2.bar(labels,[student['models'][n]['candidate_macro_f1'] for n in names],color='#0f766e');ax2.set_ylim(0,1);ax2.set_title('Student-test candidate macro F1');ax1.tick_params(axis='x',rotation=30,labelsize=7);ax2.tick_params(axis='x',rotation=30,labelsize=7);fig.tight_layout();fig.savefig(output/'f1_comparison.png',dpi=150);plt.close(fig)
